import { path } from '@servicenow/sdk-build-core'
import { createTestContext, getMergedRecordUpdates, loadTestFile } from './test-utils'

describe('Complex Object Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Fluent to XML Transformations', () => {
        test('Update Record action with TemplateValue maps configuration correctly', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(
                project,
                'flow-with-reference-column-in-flow-object.now.ts',
                'complex-objects/fluent'
            )
            expect(merged['sys_hub_flow_variable']).toHaveLength(1)
            const flowVariables = merged['sys_hub_flow_variable']

            // Validate the flow variable record
            const employeeVar = flowVariables[0]
            expect(employeeVar.element).toBe('employee')
            expect(employeeVar.label).toBe('Employee')

            // Validate attributes contain expected object metadata
            expect(employeeVar.attributes).toContain('uiType=object')
            expect(employeeVar.attributes).toContain('uiTypeLabel=Object')
            expect(employeeVar.attributes).toContain('co_type_name=FD')

            // Validate the sys_complex variable record
            expect(merged['sys_complex_object']).toHaveLength(1)
            const complexObjectVar = merged['sys_complex_object']
            const employeeCODetails = complexObjectVar[0]
            expect(employeeCODetails.type).toBe('complex_object_schema')
            expect(employeeCODetails.namespace).toBe('FlowDesigner')
            expect(employeeCODetails.serialized_content).toBeDefined()

            const serializedContent = employeeCODetails.serialized_content
            // expect(serializedContent).toContain('name')
            expect(serializedContent).toContain(`"name":"String"`)
            expect(serializedContent).toContain(`"remote":"Boolean"`)
            expect(serializedContent).toContain(`"salary":"Integer"`)
            expect(serializedContent).toContain(`"joining_date":"Date"`)
        })
    })

    describe('XML to Fluent Transformations', () => {
        test('Reference column inside FlowObject transform check', async () => {
            const project = ctx.createProject()

            const xmlContent = loadTestFile('sys_hub_flow_126aa997bbe746bea64b041392907c14.xml', 'complex-objects/xml')
            const { changedFiles } = await project.transform({
                path: 'sys_hub_flow_126aa997bbe746bea64b041392907c14.xml',
                content: xmlContent,
            })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('sys_hub_flow_126aa997bbe746bea64b041392907c14.now.ts')

            const content = changedFiles[0].getContent()

            //Verify Flow Variable inputs
            expect(content).toContain('flowVariable')
            expect(content).toContain('employee: FlowObject')
            expect(content).toContain(`label: 'Employee'`)
            expect(content).toContain('fields')
            expect(content).toContain('joining_date: DateTimeColumn')
            expect(content).toContain(`label: 'Joining Date'`)
            expect(content).toContain('name: StringColumn')
            expect(content).toContain(`label: 'Name'`)
            expect(content).toContain('remote: BooleanColumn')
            expect(content).toContain(`label: 'Remote'`)
            expect(content).toContain('salary: IntegerColumn')
            expect(content).toContain(`label: 'Salary'`)
        })
    })
})
